import{_ as r,o as t,c as o,a2 as n}from"./chunks/framework.ost63GJL.js";const d=JSON.parse('{"title":"中华人民共和国证券法（2019年修订）","description":"","frontmatter":{"title":"中华人民共和国证券法（2019年修订）"},"headers":[],"relativePath":"securities/sl/2019.md","filePath":"securities/sl/2019.md","lastUpdated":1789486139000}'),s={name:"securities/sl/2019.md"};function g(a,p,e,l,i,h){return t(),o("div",null,[...p[0]||(p[0]=[n('<h1 id="中华人民共和国证券法-2019年修订" tabindex="-1">中华人民共和国证券法（2019年修订） <a class="header-anchor" href="#中华人民共和国证券法-2019年修订" aria-label="Permalink to &quot;中华人民共和国证券法（2019年修订）&quot;">​</a></h1><h2 id="发文信息" tabindex="-1">发文信息 <a class="header-anchor" href="#发文信息" aria-label="Permalink to &quot;发文信息&quot;">​</a></h2><ul><li><strong>发文机关</strong>：全国人民代表大会常务委员会</li><li><strong>发布日期</strong>：2019-12-28</li><li><strong>生效日期</strong>：2020-03-01</li><li><strong>时效性</strong>：现行有效</li><li><strong>文号</strong>：中华人民共和国主席令第三十七号</li><li><strong>原文链接</strong>：<a href="http://www.csrc.gov.cn/" target="_blank" rel="noreferrer">证监会</a> ｜ <a href="http://www.npc.gov.cn/" target="_blank" rel="noreferrer">中国人大网</a></li></ul><blockquote><p>1998年12月29日第九届全国人民代表大会常务委员会第六次会议通过，根据2004年8月28日第十届全国人民代表大会常务委员会第十一次会议《关于修改〈中华人民共和国证券法〉的决定》第一次修正，2005年10月27日第十届全国人民代表大会常务委员会第十八次会议第一次修订，根据2013年6月29日第十二届全国人民代表大会常务委员会第三次会议《关于修改〈中华人民共和国文物保护法〉等十二部法律的决定》第二次修正，根据2014年8月31日第十二届全国人民代表大会常务委员会第十次会议《关于修改〈中华人民共和国保险法〉等五部法律的决定》第三次修正，2019年12月28日第十三届全国人民代表大会常务委员会第十五次会议第二次修订。</p></blockquote><h2 id="第一章-总则" tabindex="-1">第一章 总则 <a class="header-anchor" href="#第一章-总则" aria-label="Permalink to &quot;第一章 总则&quot;">​</a></h2><p><strong>第一条</strong>　为了规范证券发行和交易行为，保护投资者的合法权益，维护社会经济秩序和社会公共利益，促进社会主义市场经济的发展，制定本法。</p><p><strong>第二条</strong>　在中华人民共和国境内，股票、公司债券、存托凭证和国务院依法认定的其他证券的发行和交易，适用本法；本法未规定的，适用《中华人民共和国公司法》和其他法律、行政法规的规定。</p><p>政府债券、证券投资基金份额的上市交易，适用本法；其他法律、行政法规另有规定的，适用其规定。</p><p>资产支持证券、资产管理产品发行、交易的管理办法，由国务院依照本法的原则规定。</p><p>在中华人民共和国境外的证券发行和交易活动，扰乱中华人民共和国境内市场秩序，损害境内投资者合法权益的，依照本法有关规定处理并追究法律责任。</p><p><strong>第三条</strong>　证券的发行、交易活动，必须遵循公开、公平、公正的原则。</p><p><strong>第四条</strong>　证券发行、交易活动的当事人具有平等的法律地位，应当遵守自愿、有偿、诚实信用的原则。</p><p><strong>第五条</strong>　证券的发行、交易活动，必须遵守法律、行政法规；禁止欺诈、内幕交易和操纵证券市场的行为。</p><p><strong>第六条</strong>　证券业和银行业、信托业、保险业实行分业经营、分业管理，证券公司与银行、信托、保险业务机构分别设立。国家另有规定的除外。</p><p><strong>第七条</strong>　国务院证券监督管理机构依法对全国证券市场实行集中统一监督管理。</p><p>国务院证券监督管理机构根据需要可以设立派出机构，按照授权履行监督管理职责。</p><p><strong>第八条</strong>　国家审计机关依法对证券交易场所、证券公司、证券登记结算机构、证券监督管理机构进行审计监督。</p><h2 id="第二章-证券发行" tabindex="-1">第二章 证券发行 <a class="header-anchor" href="#第二章-证券发行" aria-label="Permalink to &quot;第二章 证券发行&quot;">​</a></h2><p><strong>第九条</strong>　公开发行证券，必须符合法律、行政法规规定的条件，并依法报经国务院证券监督管理机构或者国务院授权的部门注册。未经依法注册，任何单位和个人不得公开发行证券。证券发行注册制的具体范围、实施步骤，由国务院规定。</p><p>有下列情形之一的，为公开发行：</p><p>（一）向不特定对象发行证券；</p><p>（二）向特定对象发行证券累计超过二百人，但依法实施员工持股计划的员工人数不计算在内；</p><p>（三）法律、行政法规规定的其他发行行为。</p><p>非公开发行证券，不得采用广告、公开劝诱和变相公开方式。</p><p><strong>第十条</strong>　发行人申请公开发行股票、可转换为股票的公司债券，依法采取承销方式的，或者公开发行法律、行政法规规定实行保荐制度的其他证券的，应当聘请证券公司担任保荐人。</p><p>保荐人应当遵守业务规则和行业规范，诚实守信，勤勉尽责，对发行人的申请文件和信息披露资料进行审慎核查，督导发行人规范运作。</p><p>保荐人的管理办法由国务院证券监督管理机构规定。</p><p><strong>第十一条</strong>　设立股份有限公司公开发行股票，应当符合《中华人民共和国公司法》规定的条件和经国务院批准的国务院证券监督管理机构规定的其他条件，向国务院证券监督管理机构报送募股申请和下列文件：</p><p>（一）公司章程；</p><p>（二）发起人协议；</p><p>（三）发起人姓名或者名称，发起人认购的股份数、出资种类及验资证明；</p><p>（四）招股说明书；</p><p>（五）代收股款银行的名称及地址；</p><p>（六）承销机构名称及有关的协议。</p><p>依照本法规定聘请保荐人的，还应当报送保荐人出具的发行保荐书。</p><p>法律、行政法规规定设立公司必须报经批准的，还应当提交相应的批准文件。</p><p><strong>第十二条</strong>　公司首次公开发行新股，应当符合下列条件：</p><p>（一）具备健全且运行良好的组织机构；</p><p>（二）具有持续经营能力；</p><p>（三）最近三年财务会计报告被出具无保留意见审计报告；</p><p>（四）发行人及其控股股东、实际控制人最近三年不存在贪污、贿赂、侵占财产、挪用财产或者破坏社会主义市场经济秩序的刑事犯罪；</p><p>（五）经国务院批准的国务院证券监督管理机构规定的其他条件。</p><p>上市公司发行新股，应当符合经国务院批准的国务院证券监督管理机构规定的条件，具体管理办法由国务院证券监督管理机构规定。</p><p>公开发行存托凭证的，应当符合首次公开发行新股的条件以及国务院证券监督管理机构规定的其他条件。</p><p><strong>第十三条</strong>　公司公开发行新股，应当报送募股申请和下列文件：</p><p>（一）公司营业执照；</p><p>（二）公司章程；</p><p>（三）股东大会决议；</p><p>（四）招股说明书或者其他公开发行募集文件；</p><p>（五）财务会计报告；</p><p>（六）代收股款银行的名称及地址。</p><p>依照本法规定聘请保荐人的，还应当报送保荐人出具的发行保荐书。依照本法规定实行承销的，还应当报送承销机构名称及有关的协议。</p><p><strong>第十四条</strong>　公司对公开发行股票所募集资金，必须按照招股说明书或者其他公开发行募集文件所列资金用途使用；改变资金用途，必须经股东大会作出决议。擅自改变用途，未作纠正的，或者未经股东大会认可的，不得公开发行新股。</p><p><strong>第十五条</strong>　公开发行公司债券，应当符合下列条件：</p><p>（一）具备健全且运行良好的组织机构；</p><p>（二）最近三年平均可分配利润足以支付公司债券一年的利息；</p><p>（三）国务院规定的其他条件。</p><p>公开发行公司债券筹集的资金，必须按照公司债券募集办法所列资金用途使用；改变资金用途，必须经债券持有人会议作出决议。公开发行公司债券筹集的资金，不得用于弥补亏损和非生产性支出。</p><p>上市公司发行可转换为股票的公司债券，除应当符合第一款规定的条件外，还应当遵守本法第十二条第二款的规定。但是，按照公司债券募集办法，上市公司通过收购本公司股份的方式进行公司债券转换的除外。</p><p><strong>第十六条</strong>　申请公开发行公司债券，应当向国务院授权的部门或者国务院证券监督管理机构报送下列文件：</p><p>（一）公司营业执照；</p><p>（二）公司章程；</p><p>（三）公司债券募集办法；</p><p>（四）国务院授权的部门或者国务院证券监督管理机构规定的其他文件。</p><p>依照本法规定聘请保荐人的，还应当报送保荐人出具的发行保荐书。</p><p><strong>第十七条</strong>　有下列情形之一的，不得再次公开发行公司债券：</p><p>（一）对已公开发行的公司债券或者其他债务有违约或者延迟支付本息的事实，仍处于继续状态；</p><p>（二）违反本法规定，改变公开发行公司债券所募资金的用途。</p><p><strong>第十八条</strong>　发行人依法申请公开发行证券所报送的申请文件的格式、报送方式，由依法负责注册的机构或者部门规定。</p><p><strong>第十九条</strong>　发行人报送的证券发行申请文件，应当充分披露投资者作出价值判断和投资决策所必需的信息，内容应当真实、准确、完整。</p><p>为证券发行出具有关文件的证券服务机构和人员，必须严格履行法定职责，保证所出具文件的真实性、准确性和完整性。</p><p><strong>第二十条</strong>　发行人申请首次公开发行股票的，在提交申请文件后，应当按照国务院证券监督管理机构的规定预先披露有关申请文件。</p><p><strong>第二十一条</strong>　国务院证券监督管理机构或者国务院授权的部门依照法定条件负责证券发行申请的注册。证券公开发行注册的具体办法由国务院规定。</p><p>按照国务院的规定，证券交易所等可以审核公开发行证券申请，判断发行人是否符合发行条件、信息披露要求，督促发行人完善信息披露内容。</p><p>依照前两款规定参与证券发行申请注册的人员，不得与发行申请人有利害关系，不得直接或者间接接受发行申请人的馈赠，不得持有所注册的发行申请的证券，不得私下与发行申请人进行接触。</p><p><strong>第二十二条</strong>　国务院证券监督管理机构或者国务院授权的部门应当自受理证券发行申请文件之日起三个月内，依照法定条件和法定程序作出予以注册或者不予注册的决定，发行人根据要求补充、修改发行申请文件的时间不计算在内。不予注册的，应当说明理由。</p><p><strong>第二十三条</strong>　证券发行申请经注册后，发行人应当依照法律、行政法规的规定，在证券公开发行前公告公开发行募集文件，并将该文件置备于指定场所供公众查阅。</p><p>发行证券的信息依法公开前，任何知情人不得公开或者泄露该信息。</p><p>发行人不得在公告公开发行募集文件前发行证券。</p><p><strong>第二十四条</strong>　国务院证券监督管理机构或者国务院授权的部门对已作出的证券发行注册的决定，发现不符合法定条件或者法定程序，尚未发行证券的，应当予以撤销，停止发行。已经发行尚未上市的，撤销发行注册决定，发行人应当按照发行价并加算银行同期存款利息返还证券持有人；发行人的控股股东、实际控制人以及保荐人，应当与发行人承担连带责任，但是能够证明自己没有过错的除外。</p><p>股票的发行人在招股说明书等证券发行文件中隐瞒重要事实或者编造重大虚假内容，已经发行并上市的，国务院证券监督管理机构可以责令发行人回购证券，或者责令负有责任的控股股东、实际控制人买回证券。</p><p><strong>第二十五条</strong>　股票依法发行后，发行人经营与收益的变化，由发行人自行负责；由此变化引致的投资风险，由投资者自行负责。</p><p><strong>第二十六条</strong>　发行人向不特定对象发行的证券，法律、行政法规规定应当由证券公司承销的，发行人应当同证券公司签订承销协议。证券承销业务采取代销或者包销方式。</p><p>证券代销是指证券公司代发行人发售证券，在承销期结束时，将未售出的证券全部退还给发行人的承销方式。</p><p>证券包销是指证券公司将发行人的证券按照协议全部购入或者在承销期结束时将售后剩余证券全部自行购入的承销方式。</p><p><strong>第二十七条</strong>　公开发行证券的发行人有权依法自主选择承销的证券公司。</p><p><strong>第二十八条</strong>　证券公司承销证券，应当同发行人签订代销或者包销协议，载明下列事项：</p><p>（一）当事人的名称、住所及法定代表人姓名；</p><p>（二）代销、包销证券的种类、数量、金额及发行价格；</p><p>（三）代销、包销的期限及起止日期；</p><p>（四）代销、包销的付款方式及日期；</p><p>（五）代销、包销的费用和结算办法；</p><p>（六）违约责任；</p><p>（七）国务院证券监督管理机构规定的其他事项。</p><p><strong>第二十九条</strong>　证券公司承销证券，应当对公开发行募集文件的真实性、准确性、完整性进行核查。发现有虚假记载、误导性陈述或者重大遗漏的，不得进行销售活动；已经销售的，必须立即停止销售活动，并采取纠正措施。</p><p>证券公司承销证券，不得有下列行为：</p><p>（一）进行虚假的或者误导投资者的广告宣传或者其他宣传推介活动；</p><p>（二）以不正当竞争手段招揽承销业务；</p><p>（三）其他违反证券承销业务规定的行为。</p><p>证券公司有前款所列行为，给其他证券承销机构或者投资者造成损失的，应当依法承担赔偿责任。</p><p><strong>第三十条</strong>　向不特定对象发行证券聘请承销团承销的，承销团应当由主承销和参与承销的证券公司组成。</p><p><strong>第三十一条</strong>　证券的代销、包销期限最长不得超过九十日。</p><p>证券公司在代销、包销期内，对所代销、包销的证券应当保证先行出售给认购人，证券公司不得为本公司预留所代销的证券和预先购入并留存所包销的证券。</p><p><strong>第三十二条</strong>　股票发行采取溢价发行的，其发行价格由发行人与承销的证券公司协商确定。</p><p><strong>第三十三条</strong>　股票发行采用代销方式，代销期限届满，向投资者出售的股票数量未达到拟公开发行股票数量百分之七十的，为发行失败。发行人应当按照发行价并加算银行同期存款利息返还股票认购人。</p><p><strong>第三十四条</strong>　公开发行股票，代销、包销期限届满，发行人应当在规定的期限内将股票发行情况报国务院证券监督管理机构备案。</p><h2 id="第三章-证券交易" tabindex="-1">第三章 证券交易 <a class="header-anchor" href="#第三章-证券交易" aria-label="Permalink to &quot;第三章 证券交易&quot;">​</a></h2><h3 id="第一节-一般规定" tabindex="-1">第一节 一般规定 <a class="header-anchor" href="#第一节-一般规定" aria-label="Permalink to &quot;第一节 一般规定&quot;">​</a></h3><p><strong>第三十五条</strong>　证券交易当事人依法买卖的证券，必须是依法发行并交付的证券。</p><p>非依法发行的证券，不得买卖。</p><p><strong>第三十六条</strong>　依法发行的证券，《中华人民共和国公司法》和其他法律对其转让期限有限制性规定的，在限定的期限内不得转让。</p><p>上市公司持有百分之五以上股份的股东、实际控制人、董事、监事、高级管理人员，以及其他持有发行人首次公开发行前发行的股份或者上市公司向特定对象发行的股份的股东，转让其持有的本公司股份的，不得违反法律、行政法规和国务院证券监督管理机构关于持有期限、卖出时间、卖出数量、卖出方式、信息披露等规定，并应当遵守证券交易所的业务规则。</p><p><strong>第三十七条</strong>　公开发行的证券，应当在依法设立的证券交易所上市交易或者在国务院批准的其他全国性证券交易场所交易。</p><p>非公开发行的证券，可以在证券交易所、国务院批准的其他全国性证券交易场所、按照国务院规定设立的区域性股权市场转让。</p><p><strong>第三十八条</strong>　证券在证券交易所上市交易，应当采用公开的集中交易方式或者国务院证券监督管理机构批准的其他方式。</p><p><strong>第三十九条</strong>　证券交易当事人买卖的证券可以采用纸面形式或者国务院证券监督管理机构规定的其他形式。</p><p><strong>第四十条</strong>　证券交易场所、证券公司和证券登记结算机构的从业人员，证券监督管理机构的工作人员以及法律、行政法规规定禁止参与股票交易的其他人员，在任期或者法定限期内，不得直接或者以化名、借他人名义持有、买卖股票或者其他具有股权性质的证券，也不得收受他人赠送的股票或者其他具有股权性质的证券。</p><p>任何人在成为前款所列人员时，其原已持有的股票或者其他具有股权性质的证券，必须依法转让。</p><p>实施股权激励计划或者员工持股计划的证券公司的从业人员，可以按照国务院证券监督管理机构的规定持有、卖出本公司股票或者其他具有股权性质的证券。</p><p><strong>第四十一条</strong>　证券交易场所、证券公司、证券登记结算机构、证券服务机构及其工作人员应当依法为投资者的信息保密，不得非法买卖、提供或者公开投资者的信息。</p><p>证券交易场所、证券公司、证券登记结算机构、证券服务机构及其工作人员不得泄露所知悉的商业秘密。</p><p><strong>第四十二条</strong>　为证券发行出具审计报告或者法律意见书等文件的证券服务机构和人员，在该证券承销期内和期满后六个月内，不得买卖该证券。</p><p>除前款规定外，为发行人及其控股股东、实际控制人，或者收购人、重大资产交易方出具审计报告或者法律意见书等文件的证券服务机构和人员，自接受委托之日起至上述文件公开后五日内，不得买卖该证券。实际开展上述有关工作之日早于接受委托之日的，自实际开展上述有关工作之日起至上述文件公开后五日内，不得买卖该证券。</p><p><strong>第四十三条</strong>　证券交易的收费必须合理，并公开收费项目、收费标准和管理办法。</p><p><strong>第四十四条</strong>　上市公司、股票在国务院批准的其他全国性证券交易场所交易的公司持有百分之五以上股份的股东、董事、监事、高级管理人员，将其持有的该公司的股票或者其他具有股权性质的证券在买入后六个月内卖出，或者在卖出后六个月内又买入，由此所得收益归该公司所有，公司董事会应当收回其所得收益。但是，证券公司因购入包销售后剩余股票而持有百分之五以上股份，以及有国务院证券监督管理机构规定的其他情形的除外。</p><p>前款所称董事、监事、高级管理人员、自然人股东持有的股票或者其他具有股权性质的证券，包括其配偶、父母、子女持有的及利用他人账户持有的股票或者其他具有股权性质的证券。</p><p>公司董事会不按照第一款规定执行的，股东有权要求董事会在三十日内执行。公司董事会未在上述期限内执行的，股东有权为了公司的利益以自己的名义直接向人民法院提起诉讼。</p><p>公司董事会不按照第一款的规定执行的，负有责任的董事依法承担连带责任。</p><p><strong>第四十五条</strong>　通过计算机程序自动生成或者下达交易指令进行程序化交易的，应当符合国务院证券监督管理机构的规定，并向证券交易所报告，不得影响证券交易所系统安全或者正常交易秩序。</p><h2 id="第四章-上市公司的收购" tabindex="-1">第四章 上市公司的收购 <a class="header-anchor" href="#第四章-上市公司的收购" aria-label="Permalink to &quot;第四章 上市公司的收购&quot;">​</a></h2><p><strong>第六十二条</strong>　投资者可以采取要约收购、协议收购及其他合法方式收购上市公司。</p><p><strong>第六十三条</strong>　通过证券交易所的证券交易，投资者持有或者通过协议、其他安排与他人共同持有一个上市公司已发行的有表决权股份达到百分之五时，应当在该事实发生之日起三日内，向国务院证券监督管理机构、证券交易所作出书面报告，通知该上市公司，并予公告，在上述期限内不得再行买卖该上市公司的股票，但国务院证券监督管理机构规定的情形除外。</p><p>投资者持有或者通过协议、其他安排与他人共同持有一个上市公司已发行的有表决权股份达到百分之五后，其所持该上市公司已发行的有表决权股份比例每增加或者减少百分之五，应当依照前款规定进行报告和公告，在该事实发生之日起至公告后三日内，不得再行买卖该上市公司的股票，但国务院证券监督管理机构规定的情形除外。</p><p>投资者持有或者通过协议、其他安排与他人共同持有一个上市公司已发行的有表决权股份达到百分之五后，其所持该上市公司已发行的有表决权股份比例每增加或者减少百分之一，应当在该事实发生的次日通知该上市公司，并予公告。</p><p>违反第一款、第二款规定买入上市公司有表决权的股份的，在买入后的三十六个月内，对该超过规定比例部分的股份不得行使表决权。</p><p><strong>第六十四条</strong>　依照前条规定所作的公告，应当包括下列内容：</p><p>（一）持股人的名称、住所；</p><p>（二）持有的股票的名称、数额；</p><p>（三）持股达到法定比例或者持股增减变化达到法定比例的日期、增持股份的资金来源；</p><p>（四）在上市公司中拥有有表决权的股份变动的时间及方式。</p><p><strong>第六十五条</strong>　通过证券交易所的证券交易，投资者持有或者通过协议、其他安排与他人共同持有一个上市公司已发行的有表决权股份达到百分之三十时，继续进行收购的，应当依法向该上市公司所有股东发出收购上市公司全部或者部分股份的要约。</p><p>收购上市公司部分股份的要约应当约定，被收购公司股东承诺出售的股份数额超过预定收购的股份数额的，收购人按比例进行收购。</p><h2 id="第五章-信息披露" tabindex="-1">第五章 信息披露 <a class="header-anchor" href="#第五章-信息披露" aria-label="Permalink to &quot;第五章 信息披露&quot;">​</a></h2><p><strong>第七十八条</strong>　发行人及法律、行政法规和国务院证券监督管理机构规定的其他信息披露义务人，应当及时依法履行信息披露义务。</p><p>信息披露义务人披露的信息，应当真实、准确、完整，简明清晰，通俗易懂，不得有虚假记载、误导性陈述或者重大遗漏。</p><p>证券同时在境内境外公开发行、交易的，其信息披露义务人在境外披露的信息，应当在境内同时披露。</p><p><strong>第七十九条</strong>　上市公司、公司债券上市交易的公司、股票在国务院批准的其他全国性证券交易场所交易的公司，应当按照国务院证券监督管理机构和证券交易场所规定的内容和格式编制定期报告，并按照以下规定报送和公告：</p><p>（一）在每一会计年度结束之日起四个月内，报送并公告年度报告，其中的年度财务会计报告应当经符合本法规定的会计师事务所审计；</p><p>（二）在每一会计年度的上半年结束之日起二个月内，报送并公告中期报告。</p><p><strong>第八十条</strong>　发生可能对上市公司、股票在国务院批准的其他全国性证券交易场所交易的公司的股票交易价格产生较大影响的重大事件，投资者尚未得知时，公司应当立即将有关该重大事件的情况向国务院证券监督管理机构和证券交易场所报送临时报告，并予公告，说明事件的起因、目前的状态和可能产生的法律后果。</p><p>前款所称重大事件包括：</p><p>（一）公司的经营方针和经营范围的重大变化；</p><p>（二）公司的重大投资行为，公司在一年内购买、出售重大资产超过公司资产总额百分之三十，或者公司营业用主要资产的抵押、质押、出售或者报废一次超过该资产的百分之三十；</p><p>（三）公司订立重要合同、提供重大担保或者从事关联交易，可能对公司的资产、负债、权益和经营成果产生重要影响；</p><p>（四）公司发生重大债务和未能清偿到期重大债务的违约情况；</p><p>（五）公司发生重大亏损或者重大损失；</p><p>（六）公司生产经营的外部条件发生的重大变化；</p><p>（七）公司的董事、三分之一以上监事或者经理发生变动，董事长或者经理无法履行职责；</p><p>（八）持有公司百分之五以上股份的股东或者实际控制人持有股份或者控制公司的情况发生较大变化，公司的实际控制人及其控制的其他企业从事与公司相同或者相似业务的情况发生较大变化；</p><p>（九）公司分配股利、增资的计划，公司股权结构的重要变化，公司减资、合并、分立、解散及申请破产的决定，或者依法进入破产程序、被责令关闭；</p><p>（十）涉及公司的重大诉讼、仲裁，股东大会、董事会决议被依法撤销或者宣告无效；</p><p>（十一）公司涉嫌犯罪被依法立案调查，公司的控股股东、实际控制人、董事、监事、高级管理人员涉嫌犯罪被依法采取强制措施；</p><p>（十二）国务院证券监督管理机构规定的其他事项。</p><p>公司的控股股东或者实际控制人对重大事件的发生、进展产生较大影响的，应当及时将其知悉的有关情况书面告知公司，并配合公司履行信息披露义务。</p><p><strong>第八十一条</strong>　发生可能对上市交易公司债券的交易价格产生较大影响的重大事件，投资者尚未得知时，公司应当立即将有关该重大事件的情况向国务院证券监督管理机构和证券交易场所报送临时报告，并予公告，说明事件的起因、目前的状态和可能产生的法律后果。</p><p><strong>第八十二条</strong>　发行人的董事、高级管理人员应当对证券发行文件和定期报告签署书面确认意见。</p><p>发行人的监事会应当对董事会编制的证券发行文件和定期报告进行审核并提出书面审核意见。监事应当签署书面确认意见。</p><p>发行人的董事、监事和高级管理人员应当保证发行人及时、公平地披露信息，所披露的信息真实、准确、完整。</p><p><strong>第八十三条</strong>　信息披露义务人披露的信息应当同时向所有投资者披露，不得提前向任何单位和个人泄露。但是，法律、行政法规另有规定的除外。</p><p><strong>第八十四条</strong>　除依法需要披露的信息之外，信息披露义务人可以自愿披露与投资者作出价值判断和投资决策有关的信息，但不得与依法披露的信息相冲突，不得误导投资者。</p><p><strong>第八十五条</strong>　信息披露义务人未按照规定披露信息，或者公告的证券发行文件、定期报告、临时报告及其他信息披露资料存在虚假记载、误导性陈述或者重大遗漏，致使投资者在证券交易中遭受损失的，信息披露义务人应当承担赔偿责任；发行人的控股股东、实际控制人、董事、监事、高级管理人员和其他直接责任人员以及保荐人、承销的证券公司及其直接责任人员，应当与发行人承担连带赔偿责任，但是能够证明自己没有过错的除外。</p><h2 id="第六章-投资者保护" tabindex="-1">第六章 投资者保护 <a class="header-anchor" href="#第六章-投资者保护" aria-label="Permalink to &quot;第六章 投资者保护&quot;">​</a></h2><p><strong>第八十八条</strong>　证券公司向投资者销售证券、提供服务时，应当按照规定充分了解投资者的基本情况、财产状况、金融资产状况、投资知识和经验、专业能力等相关信息；如实说明证券、服务的重要内容，充分揭示投资风险；销售、提供与投资者上述状况相匹配的证券、服务。</p><p><strong>第八十九条</strong>　根据财产状况、金融资产状况、投资知识和经验、专业能力等因素，投资者可以分为普通投资者和专业投资者。专业投资者的标准由国务院证券监督管理机构规定。</p><p><strong>第九十条</strong>　上市公司董事会、独立董事、持有百分之一以上有表决权股份的股东或者依照法律、行政法规或者国务院证券监督管理机构的规定设立的投资者保护机构，可以作为征集人，自行或者委托证券公司、证券服务机构，公开请求上市公司股东委托其代为出席股东大会，并代为行使提案权、表决权等股东权利。</p><p><strong>第九十二条</strong>　公开发行公司债券的，应当设立债券持有人会议，并应当在募集说明书中说明债券持有人会议的召集程序、会议规则和其他重要事项。</p><p><strong>第九十三条</strong>　发行人因欺诈发行、虚假陈述或者其他重大违法行为给投资者造成损失的，发行人的控股股东、实际控制人、相关的证券公司可以委托投资者保护机构，就赔偿事宜与受到损失的投资者达成协议，予以先行赔付。先行赔付后，可以依法向发行人以及其他连带责任人追偿。</p><p><strong>第九十五条</strong>　投资者提起虚假陈述等证券民事赔偿诉讼时，诉讼标的是同一种类，且当事人一方人数众多的，可以依法推选代表人进行诉讼。</p><h2 id="第十三章-法律责任-部分条文节选" tabindex="-1">第十三章 法律责任（部分条文节选） <a class="header-anchor" href="#第十三章-法律责任-部分条文节选" aria-label="Permalink to &quot;第十三章 法律责任（部分条文节选）&quot;">​</a></h2><p><strong>第一百八十条</strong>　违反本法第九条的规定，擅自公开或者变相公开发行证券的，责令停止发行，退还所募资金并加算银行同期存款利息，处以非法所募资金金额百分之五以上百分之五十以下的罚款；对擅自公开或者变相公开发行证券设立的公司，由依法履行监督管理职责的机构或者部门会同县级以上地方人民政府予以取缔。对直接负责的主管人员和其他直接责任人员给予警告，并处以五十万元以上五百万元以下的罚款。</p><p><strong>第一百八十一条</strong>　发行人在其公告的证券发行文件中隐瞒重要事实或者编造重大虚假内容，尚未发行证券的，处以二百万元以上二千万元以下的罚款；已经发行证券的，处以非法所募资金金额百分之十以上一倍以下的罚款。对直接负责的主管人员和其他直接责任人员，处以一百万元以上一千万元以下的罚款。</p><p><strong>第一百九十一条</strong>　证券交易内幕信息的知情人或者非法获取内幕信息的人违反本法第五十三条的规定从事内幕交易的，责令依法处理非法持有的证券，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足五十万元的，处以五十万元以上五百万元以下的罚款。单位从事内幕交易的，还应当对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以上二百万元以下的罚款。国务院证券监督管理机构工作人员从事内幕交易的，从重处罚。</p><p><strong>第一百九十二条</strong>　违反本法第五十五条的规定，操纵证券市场的，责令依法处理其非法持有的证券，没收违法所得，并处以违法所得一倍以上十倍以下的罚款；没有违法所得或者违法所得不足一百万元的，处以一百万元以上一千万元以下的罚款。单位操纵证券市场的，还应当对直接负责的主管人员和其他直接责任人员给予警告，并处以五十万元以上五百万元以下的罚款。</p><p><strong>第一百九十七条</strong>　信息披露义务人未按照本法规定报送有关报告或者履行信息披露义务的，责令改正，给予警告，并处以五十万元以上五百万元以下的罚款；对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以上二百万元以下的罚款。</p><p><strong>第二百二十一条</strong>　违反法律、行政法规或者国务院证券监督管理机构的有关规定，情节严重的，国务院证券监督管理机构可以对有关责任人员采取证券市场禁入的措施。</p><p>前款所称证券市场禁入，是指在一定期限内直至终身不得从事证券业务、证券服务业务，不得担任证券发行人的董事、监事、高级管理人员，或者一定期限内不得在证券交易所、国务院批准的其他全国性证券交易场所交易证券的制度。</p><h2 id="第十四章-附则" tabindex="-1">第十四章 附则 <a class="header-anchor" href="#第十四章-附则" aria-label="Permalink to &quot;第十四章 附则&quot;">​</a></h2><p><strong>第二百二十四条</strong>　境内企业直接或者间接到境外发行证券或者将其证券在境外上市交易，应当符合国务院的有关规定。</p><p><strong>第二百二十五条</strong>　境内公司股票以外币认购和交易的，具体办法由国务院另行规定。</p><p><strong>第二百二十六条</strong>　本法自2020年3月1日起施行。</p><hr><blockquote><p>注：为便于学习参考，本页收录了《中华人民共和国证券法》（2019年修订）的完整章节框架及主要条文。全文完整版请参阅 <a href="http://www.csrc.gov.cn/" target="_blank" rel="noreferrer">证监会官网</a> 或 <a href="http://www.npc.gov.cn/" target="_blank" rel="noreferrer">中国人大网</a>。</p></blockquote>',192)])])}const u=r(s,[["render",g]]);export{d as __pageData,u as default};
